-- 641_card_concepts: the 100 picker place cards that had no concept lists get one (NIGHTLY_POOL_CLEANUP_PLAN.md phase 4,
-- step 1). sub_regions + must_include are authoring hints: the spot generators write to them and the pool cleanup's
-- drift check judges against them. Nothing at render time reads them. Empty lists were the root cause of drift (migs
-- 632/634: five name-only cards drifted almost wholesale).
--
-- Drafted by scripts/gen-card-concepts.js from what each card IS: its own SUBJECT_RULE (the authority), name, tile,
-- biome and era, never from its spot pool, so a drifted pool cannot write its drift into the definition (Prehistoric's
-- rule is the age of dinosaurs; its pool holds today's Stone Age monuments). Then reviewed card by card: people and
-- clothing lines dropped (a place definition, not a wardrobe), wrong facts fixed (no pier at Seaside, Bora Bora is its
-- own card, the Empty Quarter is not in Algeria), and Wild West cards held to the 1860s-1890s frontier.
--
-- Guarded: only cards whose lists are still both empty. Data only. Re-runnable.

UPDATE public.location_cards SET sub_regions = ARRAY['Main Street commercial strip (five-and-dime storefronts, soda fountains, barbershops with striped poles, marquee movie theaters, neon-lit diners)', 'Route 66 roadside corridor (Googie coffee shops, Burma-Shave sign sequences, motor courts, giant roadside novelties, filling stations with winged canopy roofs)', 'Drive-in theater grounds (speaker-post rows, projection booth tower, snack bar pavilion, neon marquee at the entrance lane)', 'Postwar suburban neighborhood (ranch houses with carports, cul-de-sac lawns, backyard barbecue patios, television aerials, pastel-painted tract homes)', 'Small-town civic center (red brick high school with steel-framed windows, grain elevator at the rail siding, bandstand in the park square, corner drugstore)', 'Roadside motel court (horseshoe-plan cabins, exterior-corridor rooms with numbered parking slots, lit vacancy sign, kidney-shaped pool with wrought-iron fence)']::text[], must_include = ARRAY['neon signage, chrome trim, and Googie rooflines as architectural focal points', 'postwar optimism rendered in saturated color — turquoise, coral, canary yellow, and fire-engine red', 'period-specific built fabric: twin-canopy gas stations, Burma-Shave boards, drive-in speaker posts, ranch-house carports', 'monumental framing of vernacular structures — the diner or the motel as the hero of the composition', 'never modernized storefronts, today''s heritage signage, or any era outside the postwar 1950s American built environment']::text[]
  WHERE name = '1950s americana' AND cardinality(coalesce(sub_regions, ARRAY[]::text[])) = 0
    AND cardinality(coalesce(must_include, ARRAY[]::text[])) = 0;
UPDATE public.location_cards SET sub_regions = ARRAY['Central Green & Amphitheater (Ruskin Place artist square, the grassy Central Square lawn, the open-air amphitheater bandshell)', 'Seaside Beach & Dune Pavilions (the sugar-white shoreline, the iconic wooden beach pavilions cresting the dunes, the Gulf-side sunbathing flats)', 'Cottage Streets & Picket Lanes (Tupelo Street, Savannah Street, the pastel and white-painted cottages behind white picket fences, the brick-paved pedestrian lanes)', 'Airstream Food Court Row (the retro silver Airstream trailer vendors along 30A, the shaded picnic areas, the casual open-air dining green)', 'Rosemary Beach & Alys Beach (brick lanes, Dutch West Indies townhouses, all-white courtyards and palm-lined walks along 30A)', 'Grayton Beach & the coastal dune lakes (rare dune lakes meeting the Gulf, old-Florida cottages, sea oats)']::text[], must_include = ARRAY['sugar-white sand and emerald Gulf water under bright coastal light', 'pastel and crisp-white raised wood-frame cottages with metal standing-seam roofs, deep covered porches, and white picket fences', 'whimsical open-air timber beach pavilions cresting the dunes', 'brick pedestrian lanes and cruiser bikes leaning at cottage gates', 'the 30A beach towns and their Gulf shore, never inland Florida or a high-rise resort strip such as Destin or Panama City Beach']::text[]
  WHERE name = '30a' AND cardinality(coalesce(sub_regions, ARRAY[]::text[])) = 0
    AND cardinality(coalesce(must_include, ARRAY[]::text[])) = 0;
UPDATE public.location_cards SET sub_regions = ARRAY['Floating magnetic rock islands (suspension archipelagos drifting above mineral-stained cloudbanks, tethered by electromagnetic force to basalt anchor columns below)', 'Crystalline silicon-flora forest (vast groves of translucent silicate trees refracting dual-sun light into prismatic ground-scatter, growing in cathedral-scale clusters)', 'Hexagonal violet basalt plain (immense tessellated flatlands of cooling lava geometry stretching to the horizon, cracked into perfect polygonal tiles glowing faintly at their seams)', 'Obsidian cliff face bioluminescent colony (sheer black glass escarpments alive with pulsing organisms coating the rock in shifting teal and gold light patterns across thousands of vertical metres)', 'Ammonia-ice geyser field (frozen lowland plains erupting in towering crystalline plumes that catch moonlight and rain ice-crystal fallout across the surrounding terrain)', 'Ring-arc shadow corridor (the belt of terrain where the planet''s ring-arc casts its sweeping geometric shadow, creating a perpetual amber-lit transitional zone between full-sun and eclipse)']::text[], must_include = ARRAY['one monumental megafeature dominating the frame at terrain-dwarfing scale', 'alien sky anchored by dual suns, a ring-arc, or triple moons', 'otherworldly colour palette — violet, obsidian, bioluminescent teal, prismatic silicate light', 'geological or biological texture that reads as non-terrestrial in origin', 'never Earth landscapes, Earth sky conditions, or recognisable terrestrial biomes substituted for the alien megafeatures']::text[]
  WHERE name = 'alien planet' AND cardinality(coalesce(sub_regions, ARRAY[]::text[])) = 0
    AND cardinality(coalesce(must_include, ARRAY[]::text[])) = 0;
